func (a audit) Append(ctx context.Context, entry domain.AuditEntry) (domain.OperationStats, error) {
	started := time.Now()
	err := a.port.AppendAnnouncementAudit(ctx, recordports.AuditEntry{OperatorID: entry.OperatorID, Action: entry.Action, ResourceID: entry.ResourceID, RequestIP: entry.RequestIP, Changes: entry.Changes})
	stats := domain.OperationStats{Queries: 1, StatementDuration: time.Since(started)}
	if err == nil {
		stats.Rows = 1
	}
	return stats, err
}

