func (e *Emitter) BroadcastChildUpdateToGuardians(tenantID, studentID int64) {
	if e == nil || e.events == nil {
		return
	}
	if tenantID <= 0 || studentID <= 0 {
		return
	}
	e.events.WakeChildGuardians(tenantID, studentID)
}

func (e *Emitter) EmitChildEvent(ctx context.Context, tenantID, studentID, guardianAccountID int64, ev eventContract.ChildEvent) error {
	if e == nil || e.events == nil {
		return nil
	}
	if tenantID <= 0 || studentID <= 0 || guardianAccountID <= 0 {
		return nil
	}
	return e.events.EmitChildEvent(ctx, tenantID, studentID, guardianAccountID, ev)
}

func (e *Emitter) MessagingEnabledForTenant(ctx context.Context, tenantID int64) bool {
	if e == nil || e.events == nil {
		return true
	}
	return e.events.MessagingEnabledForTenant(ctx, tenantID)
}

func (s *service) AnnouncementEditable(ctx context.Context, announcementID int64) (bool, error) {
	a, err := s.repo.FindByID(ctx, announcementID)
	if err != nil {
		return false, fmt.Errorf("announcement: load for attachment check: %w", err)
	}
	if a == nil {
		return false, nil
	}
	return s.attachmentsEditable(ctx, a)
}

func (s *service) AnnouncementExists(ctx context.Context, announcementID int64) (bool, error) {
	a, err := s.repo.FindByID(ctx, announcementID)
	if err != nil {
		return false, fmt.Errorf("announcement: load for attachment check: %w", err)
	}
	return a != nil, nil
}

func (s *service) DeclarationFrozen(ctx context.Context, a *StaffParentAnnouncement) (bool, error) {
	if !a.IsDeclaration() {
		return false, nil
	}
	version, err := s.repo.LatestDeclarationVersion(ctx, a.GetTenantID(), a.ID)
	if err != nil {
		return false, fmt.Errorf("announcement: load declaration version: %w", err)
	}
	return version != nil, nil
}

func (s *service) LockAnnouncementForAttachmentChange(ctx context.Context, announcementID int64) (bool, bool, error) {
	a, err := s.repo.FindByIDForUpdate(ctx, announcementID)
	if err != nil {
		return false, false, fmt.Errorf("announcement: lock for attachment change: %w", err)
	}
	if a == nil {
		return false, false, nil
	}
	editable, err := s.attachmentsEditable(ctx, a)
	return true, editable, err
}

